class Solution {
public:
    int minimumMoves(vector<int>& arr) {
        int n = arr.size();
        if (n == 0) {
            return 0;
        }
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = n - 1; i >= 0; --i) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; ++j) {
                dp[i][j] = 1 + dp[i + 1][j];
                if (arr[i] == arr[i + 1]) {
                    dp[i][j] = min(dp[i][j], 1 + (i + 2 <= j ? dp[i + 2][j] : 0));
                }
                for (int k = i + 2; k <= j; ++k) {
                    if (arr[i] == arr[k]) {
                        int middle = dp[i + 1][k - 1];
                        int suffix = k < j ? dp[k + 1][j] : 0;
                        dp[i][j] = min(dp[i][j], middle + suffix);
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
};
